var page = 0;
var n = "";
for(var i=json.length - 1; i >= 0; i--){
	if(json[i].ctype === "1"){
		n = json[i].title;
		json.splice(i, 1);
		continue;
		}
	page = json[i]["ordernum"];
	json[i]["url"] = source.getKey() + "/read/" + bid + "/p" + page + ".html";
	json[i]["n"] = n;
	}
json;

